const poets_poet_t *poets_poet_by_id(const char *id)
{
    for (int i = 0; i < POETS_POET_COUNT; i++) {
        const poets_poet_t *p = g_poets[i];
        if (p->id[0] == id[0] && __builtin_strcmp(p->id, id) == 0) {
            return p;
        }
    }
    return NULL;
}
